            final(self).id() == old(self).id(),
            res == old(self).resource(),
            final(self).is_resource_owner(),
            final(self).has_no_resource(),
            final(self).frac() == old(self).frac(),
            final(self).wf(),
    {
        unimplemented!()
    }

    #[verifier::external_body]
