        }
        let guard = G::guard();
        let lock =
            atomic_with_ghost!(
            self.lock => fetch_or(UPGRADEABLE_READER);
            update prev -> next;
            ghost g => {
            }
        )
            & (WRITER | UPGRADEABLE_READER);
