impl<T               , G: SpinGuardian> RwLock<T, G> {
    pub fn try_upread(&self) -> Option<RwLockUpgradeableGuard<'_, T, G>> {
        proof_decl!{
            let tracked mut upgrade_guard_token: Option<OneLeftOwner<HalfPerm<T>, NoPerm<T>, 3>> = None;
            let tracked mut retract_upgrade_token: Option<UniqueToken> = None;
            let ghost mut current_value: usize = 0;
        }
        proof!{
            use_type_invariant(self);
            lemma_consts_properties();
        }
        let guard = G::guard();
        let lock =
            atomic_with_ghost!(
            self.lock => fetch_or(UPGRADEABLE_READER);
            update prev -> next;
            ghost g => {
                lemma_consts_properties_prev_next(prev as usize, next as usize);
                lemma_consts_properties_value(prev as usize);
                current_value = next as usize;
                lemma_consts_properties_value(current_value);
                assert(current_value & UPGRADEABLE_READER != 0);
                assert(current_value >= UPGRADEABLE_READER);
                if prev & (WRITER | UPGRADEABLE_READER) == 0 {
                    let tracked token = match g.upreader_guard_token {
                        Some(token) => token,
                        None => proof_from_false(),
                    };
                    g.upreader_guard_token = None;
                    upgrade_guard_token = Some(token);
                } else if prev & (WRITER | UPGRADEABLE_READER) == WRITER {
                    let tracked token = match g.upread_retract_token {
                        Some(token) => token,
                        None => proof_from_false(),
                    };
                    g.upread_retract_token = None;
                    retract_upgrade_token = Some(token);
                }
            }
        )
            & (WRITER | UPGRADEABLE_READER);
        if lock == 0 {
            return Some(
                RwLockUpgradeableGuard {
                    inner: self,
                    guard,
                    tracked_token: Tracked(upgrade_guard_token.tracked_unwrap()),
                },
            );
        } else if lock == WRITER {
            atomic_with_ghost!(
                self.lock => no_op();
                update prev -> next;
                ghost g => {
                    assert(g.upread_retract_token is None);
                    assert(prev & UPGRADEABLE_READER != 0);
